package matrixir
import("encoding/csv";"io";"os";"path/filepath";"sort";"strconv")
func LoadExecutionReadyTables(dir,language string)(RealTables,error){t,e:=LoadRealTables(dir,language);if e!=nil{return t,e};t.Predicates=map[string][]LexPredicateInstruction{};t.CharacterSets=map[string][]LexCharacterRange{};read:=func(n string)([][]string,error){f,e:=os.Open(filepath.Join(dir,n));if e!=nil{return nil,e};defer f.Close();r:=csv.NewReader(f);r.FieldsPerRecord=-1;if _,e=r.Read();e!=nil{return nil,e};var o [][]string;for{v,e:=r.Read();if e==io.EOF{break};if e!=nil{return nil,e};o=append(o,v)};return o,nil};ai:=func(s string)int{v,_:=strconv.Atoi(s);return v};if x,e:=read("lex_predicate_bytecode.csv");e==nil{for _,r:=range x{if len(r)>=7&&r[1]==language{p:=LexPredicateInstruction{r[0],ai(r[3]),r[4],r[5],r[6]};t.Predicates[p.PredicateID]=append(t.Predicates[p.PredicateID],p)}}};for k:=range t.Predicates{sort.Slice(t.Predicates[k],func(i,j int)bool{return t.Predicates[k][i].Ordinal<t.Predicates[k][j].Ordinal})};if x,e:=read("lex_character_sets.csv");e==nil{for _,r:=range x{if len(r)>=5&&r[0]==language{t.CharacterSets[r[1]]=append(t.CharacterSets[r[1]],LexCharacterRange{r[1],ai(r[3]),ai(r[4])})}}};return t,nil}
